import { useId, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

export type RegistrationData = {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type Props = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const SUMMARY: ReadonlyArray<[keyof RegistrationData, string]> = [
  ['fullName', 'Имя и фамилия'],
  ['email', 'Email'],
  ['phone', 'Телефон'],
  ['country', 'Страна'],
  ['city', 'Город'],
  ['street', 'Улица, дом'],
  ['zip', 'Индекс'],
];

export default function RegistrationWizard({ onSubmit }: Props) {
  const baseId = useId();
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY_DATA);

  const isLast = step === STEPS.length - 1;

  const update = (key: keyof RegistrationData) => (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const { value } = event.target;
    setData((prev) => ({ ...prev, [key]: value }));
  };

  const field = (key: keyof RegistrationData, label: string, type = 'text') => (
    <div
      className="jx-field"
      style={{ display: 'grid', gap: 'var(--jx-space-1)' }}
    >
      <label className="jx-label" htmlFor={`${baseId}-${key}`}>
        {label}
      </label>
      <input
        className="jx-input"
        id={`${baseId}-${key}`}
        type={type}
        value={data[key]}
        onChange={update(key)}
      />
    </div>
  );

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(data);
    } else {
      setStep((prev) => prev + 1);
    }
  };

  return (
    <form
      className="jx-card"
      onSubmit={handleSubmit}
      style={{ display: 'grid', gap: 'var(--jx-space-5)' }}
    >
      <ol
        className="jx-stepper"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-3)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((title, index) => (
          <li
            key={title}
            className="jx-stepper__step"
            aria-current={index === step ? 'step' : undefined}
            style={{
              flex: 1,
              display: 'grid',
              gap: 'var(--jx-space-1)',
              color:
                index === step ? 'var(--jx-color-text)' : 'var(--jx-color-text-muted)',
            }}
          >
            <span
              style={{
                height: 'var(--jx-space-1)',
                borderRadius: 'var(--jx-radius-full)',
                background:
                  index <= step
                    ? 'var(--jx-color-primary)'
                    : 'var(--jx-color-border)',
              }}
            />
            <span className="jx-text-sm">
              {index + 1}. {title}
            </span>
          </li>
        ))}
      </ol>

      <div style={{ display: 'grid', gap: 'var(--jx-space-4)' }}>
        {step === 0 && (
          <>
            {field('fullName', 'Имя и фамилия')}
            {field('email', 'Email', 'email')}
            {field('phone', 'Телефон', 'tel')}
          </>
        )}

        {step === 1 && (
          <>
            {field('country', 'Страна')}
            {field('city', 'Город')}
            {field('street', 'Улица, дом')}
            {field('zip', 'Индекс')}
          </>
        )}

        {step === 2 && (
          <dl style={{ display: 'grid', gap: 'var(--jx-space-2)', margin: 0 }}>
            {SUMMARY.map(([key, label]) => (
              <div
                key={key}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-3)',
                }}
              >
                <dt className="jx-text-sm" style={{ color: 'var(--jx-color-text-muted)' }}>
                  {label}
                </dt>
                <dd style={{ margin: 0 }}>{data[key] || '—'}</dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep((prev) => Math.max(0, prev - 1))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

